/** Power · alternate value above a dp threshold · text → device px. */
export const pwwspQualifierPx = /* @__PURE__ */ qualifierFn(B, DpQualifier.WIDTH, KIND_SP, true);
/** Power · alternate value for UI mode + dp threshold · text → CSS px. */
export const pwwspScreen = /* @__PURE__ */ screenFn(B, DpQualifier.WIDTH, KIND_SP, false);
/** Power · alternate value for UI mode + dp threshold · text → device px. */
export const pwwspScreenPx = /* @__PURE__ */ screenFn(B, DpQualifier.WIDTH, KIND_SP, true);

// ── Builder (Android `DimenPower` / `PowerSp`). ───────────────────────────
/** Custom-dimension builder for the power strategy. */
export class DimenPower extends DimenBuilder {
  get pwsdp(): number { return this.sdp; }
  get pwsdpPx(): number { return this.sdpPx; }
  get pwssp(): number { return this.ssp; }
  get pwsspPx(): number { return this.sspPx; }
  get pwsem(): number { return this.sem; }
  get pwsemPx(): number { return this.semPx; }
  get pwhdp(): number { return this.hdp; }
  get pwhdpPx(): number { return this.hdpPx; }
  get pwhsp(): number { return this.hsp; }
  get pwhspPx(): number { return this.hspPx; }
  get pwhem(): number { return this.hem; }
  get pwhemPx(): number { return this.hemPx; }
  get pwwdp(): number { return this.wdp; }
  get pwwdpPx(): number { return this.wdpPx; }
  get pwwsp(): number { return this.wsp; }
  get pwwspPx(): number { return this.wspPx; }
  get pwwem(): number { return this.wem; }
  get pwwemPx(): number { return this.wemPx; }
}
/** Starts a builder: `powerDp(16).screen(UiModeType.TELEVISION, 40).pwsdp`. */
export const powerDp = (value: number): DimenPower => new DimenPower(B, value);
/** Text builder (same class; read `.pwssp` / `.pwsem`). */
export const powerSp = (value: number): DimenPower => new DimenPower(B, value);
